  v8_atA M v y -> L5.defined M' v 24 -> L5C.agree_on M M' v 24 -> PMFA.agsh M M' v 24 -> 0 <= v -> v + 24 <= 2 ^ 47 ->
  (forall b n c, y = PGV8.V8Blk b n c -> L5.defined M' b c /\ PMFA.agsh M M' b c) -> v8_atA M' v y.
Proof.
