  getr R (reg 1) = Z_to_bv 64 873888 -> getr R (reg 2) = Z_to_bv 64 (S - 96) -> getr R (reg 10) = Z_to_bv 64 v -> getr R (reg 11) = Z_to_bv 64 (S - 88) -> kept0 R ->
